// ============================================================
// Mục tiêu: lấy được DANH SÁCH URL BÀI GỐC (cafef/vietstock...) để đưa Jina đọc full.
// Link Google News bị Jina chặn 451 -> thử lấy URL qua RSS đọc bằng Jina.
// ============================================================
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36';
const H = { 'User-Agent': UA, 'Accept': 'text/plain, */*' };

const jina = async (url) => {
  const res = await this.helpers.httpRequest({ method: 'GET', url: 'https://r.jina.ai/' + url, headers: H, json: false, timeout: 30000 });
  return typeof res === 'string' ? res : String(res);
};

const out = [];

// Các RSS báo VN (đọc qua Jina để né chặn IP)
const rssList = [
  { name: 'CafeF CK', url: 'https://cafef.vn/thi-truong-chung-khoan.rss' },
  { name: 'CafeF DN', url: 'https://cafef.vn/doanh-nghiep.rss' },
  { name: 'Vietstock', url: 'https://vietstock.vn/145/chung-khoan/thi-truong.rss' },
];

for (const r of rssList) {
  try {
    const body = await jina(r.url);
    // Tìm URL bài gốc: cafef.vn/...html|.chn  hoặc  vietstock.vn/...htm
    const urls = (body.match(/https?:\/\/(?:[a-z]+\.)?(?:cafef\.vn|vietstock\.vn)\/[^\s)\]"'>]+\.(?:html?|chn)/gi) || []);
    const uniq = [...new Set(urls)].slice(0, 5);
    out.push({ json: { rss: r.name, status: '✅ Jina đọc được (' + body.length + ' ký tự)', soBaiTimThay: uniq.length, mauURL: uniq } });
  } catch (e) {
    out.push({ json: { rss: r.name, status: '❌ ' + (e.message || String(e)), soBaiTimThay: 0, mauURL: [] } });
  }
}

// Nếu tìm được 1 URL bài, thử Jina đọc full bài đó để xác nhận có nội dung
let firstArticle = '';
for (const o of out) { if (o.json.mauURL && o.json.mauURL.length) { firstArticle = o.json.mauURL[0]; break; } }
if (firstArticle) {
  try {
    const art = await jina(firstArticle);
    out.push({ json: { rss: '>>> TEST đọc full 1 bài', status: '✅ (' + art.length + ' ký tự)', url: firstArticle, sample: art.replace(/\s+/g, ' ').slice(0, 500) } });
  } catch (e) {
    out.push({ json: { rss: '>>> TEST đọc full 1 bài', status: '❌ ' + (e.message || String(e)), url: firstArticle } });
  }
}

return out;
